17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.Locale;
23	
24	/**
25	 * Helpers for the "household" a pet owner belongs to. Two owners share a household when they have
26	 * the same last name at the same address; the identity is keyed on those two values normalized the
27	 * same way (surrounding whitespace trimmed, internal whitespace runs collapsed to a single space,
28	 * lower-cased) so values that differ only in letter case or spacing map to one household.
29	 */
30	public final class Households {
31	
32	    private Households() {
33	    }
34	
35	    /**
36	     * Normalizes a value for household comparison: {@code null} becomes an empty string, surrounding
37	     * whitespace is trimmed, internal runs of whitespace collapse to a single space and the result is
38	     * lower-cased.
39	     */
40	    public static String normalize(String value) {
41	        if (value == null) {
42	            return "";
43	        }
44	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
45	    }
46	
47	    /**
48	     * Returns the stable, shared identifier for the household of the owner with the given last name
49	     * and address. The value is derived deterministically from the normalized last name and address,
50	     * so every owner in the same household (same normalized last name and address) is assigned the
51	     * same identifier, formatted {@code 'HH-<12 upper-case hex chars>'} (e.g. {@code 'HH-3A7F9C2E1B08'}).
52	     *
53	     * @param lastName the owner's last name
54	     * @param address  the owner's address
55	     * @return the household identifier
56	     */
57	    public static String householdId(String lastName, String address) {
58	        String key = normalize(lastName) + "\n" + normalize(address);
59	        return "HH-" + sha256hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
60	    }
61	
62	    /**
63	     * Builds an owner's {@code identityKey}: the single derived value all duplicate detection is
64	     * expressed through, formatted {@code '<telephone>|<email or empty>|<householdId>'} (a
65	     * {@code null} telephone or email contributes an empty segment). Two owners are duplicates only
66	     * when their whole identity keys are equal, so household members sharing a {@code householdId} but
67	     * carrying different telephones have different keys and are not duplicates.
68	     *
69	     * @param telephone   the owner's normalized (E.164) telephone
70	     * @param email       the owner's normalized email, or {@code null} when none
71	     * @param householdId the owner's household identifier (see {@link #householdId})
72	     * @return the derived identity key
73	     */
74	    public static String identityKey(String telephone, String email, String householdId) {
75	        return (telephone == null ? "" : telephone) + "|"
76	            + (email == null ? "" : email) + "|"
77	            + (householdId == null ? "" : householdId);
78	    }
79	
80	    private static String sha256hex(String s) {
81	        try {
82	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
83	            StringBuilder sb = new StringBuilder(digest.length * 2);
84	            for (byte b : digest) {
85	                sb.append(String.format("%02x", b));
86	            }
87	            return sb.toString();
88	        }
89	        catch (NoSuchAlgorithmException e) {
90	            throw new IllegalStateException("SHA-256 not available", e);
91	        }
92	    }
93	}
