16	
17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
32	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
34	import org.springframework.samples.petclinic.rest.advice.InvalidAddressException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
37	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.util.Households;
47	import org.springframework.samples.petclinic.util.Localities;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /**
66	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
67	     * new owner's id, its assigned {@code customerCode}, its {@code registrationDate} and its
68	     * numeric {@code membershipLevel}.
69	     */
70	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
121	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
122	        if (registrationDate == null) {
123	            registrationDate = java.time.LocalDate.now();
124	        }
125	        registrationDate = toBusinessDay(registrationDate);
126	        owner.setRegistrationDate(registrationDate);
127	        rejectDailyLimitReached(registrationDate);
128	        rejectCityAtCapacity(owner.getCity());
129	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
130	        owner.setTelephone(telephone);
131	        String email = normalizeEmail(ownerFieldsDto.getEmail());
132	        owner.setEmail(email);
133	        owner.setPostcode(validatePostcode(owner.getCity(), ownerFieldsDto.getPostcode()));
134	        rejectDuplicateIdentity(owner);
135	        owner.setCustomerCode(assignCustomerCode(owner.getCity(), owner.getLastName()));
136	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
137	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
138	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getAddress()) + 1);
139	        this.clinicService.saveOwner(owner);
140	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
141	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
142	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
143	            ownerDto.getMembershipLevel());
144	        headers.setLocation(UriComponentsBuilder.newInstance()
145	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
146	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
147	    }
148	
149	    /**
150	     * The maximum number of owners that may be created in a single day. Creating an owner once this
151	     * many owners already carry today's {@code registrationDate} is rejected.
152	     */
153	    private static final int DAILY_OWNER_LIMIT = 100;
154	
155	    /**
156	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
157	     * given business day as their {@code registrationDate}. The count is keyed by the
158	     * business-day-adjusted registration date of the owner being created (see
159	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
160	     * with no {@code registrationDate} are ignored.
161	     *
162	     * @param registrationDate the business-day-adjusted registration date of the owner being created
163	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
164	     */
165	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
166	        long count = this.clinicService.findAllOwners().stream()
167	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
168	            .count();
169	        if (count >= DAILY_OWNER_LIMIT) {
170	            throw new DailyOwnerLimitException(registrationDate);
171	        }
172	    }
173	
174	    /**
175	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
176	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
177	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
178	     */
179	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
180	
181	    /**
182	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
183	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
184	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
185	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
186	     * owner being created is excluded (it has not yet been saved).
187	     *
188	     * @param registrationDate the business-day-adjusted registration date of the owner being created
189	     * @return {@code true} if more than the threshold of owners already carry this business day
190	     */
191	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
192	        long count = this.clinicService.findAllOwners().stream()
193	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
194	            .count();
195	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
196	    }
197	
198	    /**
199	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is moved forward to
200	     * the following Monday; a weekday is returned unchanged. This applies to the effective
201	     * registration date whether it was supplied in the request or defaulted to the server date, and
202	     * every value derived from the registration date uses the adjusted result.
203	     *
204	     * @param date the effective registration date
205	     * @return {@code date} itself when it is a weekday, otherwise the following Monday
206	     */
207	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
208	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
209	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
210	            date = date.plusDays(1);
211	        }
212	        return date;
213	    }
214	
215	    /**
216	     * The maximum number of owners a single city may contain. Creating an owner in a city that
217	     * already holds this many owners is rejected.
218	     */
219	    private static final int CITY_CAPACITY = 50;
220	
221	    /**
222	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
223	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
224	     * treated as empty), the same way {@link #assignCustomerCode} counts a city's owners.
225	     *
226	     * @param city the city of the owner being created
227	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
228	     */
229	    private void rejectCityAtCapacity(String city) {
230	        String cityValue = city == null ? "" : city;
231	        long count = this.clinicService.findAllOwners().stream()
232	            .filter(existing -> cityValue.equalsIgnoreCase(
233	                existing.getCity() == null ? "" : existing.getCity()))
234	            .count();
235	        if (count >= CITY_CAPACITY) {
236	            throw new CityAtCapacityException(city);
237	        }
238	    }
239	
240	    /**
241	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
242	     * where CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first
243	     * three letters of the last name and NNNN a per-city 4-digit zero-padded sequence equal to one
244	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
245	     *
246	     * @param city the owner's city
247	     * @param lastName the owner's last name
248	     * @return the assigned customer code
249	     */
250	    private String assignCustomerCode(String city, String lastName) {
251	        String city3 = prefix3(city);
252	        String last3 = prefix3(lastName);
253	        String cityValue = city == null ? "" : city;
254	        int sequence = (int) this.clinicService.findAllOwners().stream()
255	            .filter(existing -> cityValue.equalsIgnoreCase(
256	                existing.getCity() == null ? "" : existing.getCity()))
257	            .count() + 1;
258	        return String.format("%s-%s-%04d", city3, last3, sequence);
259	    }
260	
261	    /**
262	     * Returns the upper-cased first three letters of the given value, or fewer if the value is
263	     * shorter, treating {@code null} as empty.
264	     */
265	    private String prefix3(String value) {
266	        String name = value == null ? "" : value;
267	        return name.substring(0, Math.min(3, name.length()))
268	            .toUpperCase(java.util.Locale.ROOT);
269	    }
270	
271	    /**
272	     * Counts how many existing owners share the given first and last name, compared
273	     * case-insensitively, at the time this owner is created. The value excludes the owner
274	     * being created (which has not yet been saved) and is stored on the new owner and returned
275	     * as its {@code namesakeCount}.
276	     *
277	     * @param firstName the first name of the owner being created
278	     * @param lastName the last name of the owner being created
279	     * @return the number of existing owners with the same first and last name
280	     */
281	    private int countNamesakes(String firstName, String lastName) {
282	        String first = firstName == null ? "" : firstName;
283	        String last = lastName == null ? "" : lastName;
284	        return (int) this.clinicService.findAllOwners().stream()
285	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
286	                && last.equalsIgnoreCase(existing.getLastName()))
287	            .count();
288	    }
289	
290	    /**
291	     * Counts how many existing owners belong to the same household as the owner being created, i.e.
292	     * share its {@code householdId} (derived by {@link Households#householdId} from the normalized last
293	     * name and address). The value excludes the owner being created (which has not yet been saved), so
294	     * the household's size after this create is this count plus one. It is stored on the new owner.
295	     *
296	     * @param lastName the last name of the owner being created
297	     * @param address the normalized address of the owner being created
298	     * @return the number of existing owners sharing this owner's household
299	     */
300	    private int countHouseholdMembers(String lastName, String address) {
301	        String householdId = Households.householdId(lastName, address);
302	        return (int) this.clinicService.findAllOwners().stream()
303	            .filter(existing -> householdId.equals(
304	                Households.householdId(existing.getLastName(), existing.getAddress())))
305	            .count();
306	    }
307	
308	    /**
309	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
310	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
311	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
312	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
313	     * {@code "+61412345678"}. The E.164 value is stored and returned.
314	     * <p>
315	     * The national-number length (the digits after the country code) is additionally validated for
316	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
317	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
318	     *
319	     * @param telephone the raw telephone as submitted
320	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
321	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
322	     *         or its national-number length is wrong for its country code
323	     */
324	    private String normalizeTelephone(String telephone) {
325	        String raw = telephone == null ? "" : telephone.trim();
326	        boolean hasCountryCode = raw.startsWith("+");
327	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
328	        if (hasCountryCode) {
329	            cleaned = cleaned.substring(1);
330	        }
331	        String digits;
332	        if (hasCountryCode) {
333	            digits = cleaned;
334	        } else {
335	            if (cleaned.startsWith("0")) {
336	                cleaned = cleaned.substring(1);
337	            }
338	            digits = "61" + cleaned;
339	        }
340	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
341	            throw new InvalidTelephoneException(telephone);
342	        }
343	        return "+" + digits;
344	    }
345	
346	    /**
347	     * Checks the national-number length of an E.164 digit string against its country code for the
348	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
349	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
350	     *
351	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
352	     * @return {@code true} if the national-number length is acceptable for the country code
353	     */
354	    private boolean hasValidNationalLength(String digits) {
355	        if (digits.startsWith("61")) {
356	            return digits.length() - 2 == 9;
357	        }
358	        if (digits.startsWith("1")) {
359	            return digits.length() - 1 == 10;
360	        }
361	        return true;
362	    }
363	
364	    /**
365	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
366	     * multi-character top-level label. Deliberately lenient about the exact character set while still
367	     * rejecting values that are clearly not addresses (e.g. missing '@').
368	     */
369	    private static final java.util.regex.Pattern EMAIL_PATTERN =
370	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
371	
372	    /**
373	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
374	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
375	     * lower-cased before being stored and returned.
376	     *
377	     * @param email the raw email as submitted, may be {@code null}
378	     * @return the lower-cased email, or {@code null} when none was supplied
379	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
380	     */
381	    private String normalizeEmail(String email) {
382	        if (email == null || email.isBlank()) {
383	            return null;
384	        }
385	        String trimmed = email.trim();
386	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
387	            throw new InvalidEmailException(email);
388	        }
389	        return trimmed.toLowerCase(java.util.Locale.ROOT);
390	    }
391	
392	    /**
393	     * Fixed region-to-postcode-range table: a region's postcode must fall within its inclusive range
394	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose region is not listed here (see
395	     * {@link Localities#region}) accepts any 4-digit postcode.
396	     */
397	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
398	        "NSW", new int[] {2000, 2099},
399	        "VIC", new int[] {3000, 3099},
400	        "QLD", new int[] {4000, 4099});
401	
402	    /**
403	     * Validates an owner's postcode on create. The postcode is optional: a {@code null} or blank value
404	     * is left as {@code null} (no postcode) and accepted. When present it must be exactly 4 digits and,
405	     * for a city whose region is in the fixed {@link #REGION_POSTCODE_RANGES range table}, must fall
406	     * within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
407	     * known region accepts any 4-digit postcode. The value is stored and returned exactly as supplied.
408	     *
409	     * @param city the owner's city, used to derive the region whose range constrains the postcode
410	     * @param postcode the raw postcode as submitted, may be {@code null}
411	     * @return the postcode when supplied, or {@code null} when none was supplied
412	     * @throws InvalidPostcodeException (400 Bad Request) if a supplied postcode is not 4 digits or is
413	     *         out of range for the city's region
414	     */
415	    private String validatePostcode(String city, String postcode) {
416	        if (postcode == null || postcode.isBlank()) {
417	            return null;
418	        }
419	        if (!postcode.matches("[0-9]{4}")) {
420	            throw new InvalidPostcodeException(postcode);
421	        }
422	        int[] range = REGION_POSTCODE_RANGES.get(Localities.region(city));
423	        if (range != null) {
424	            int value = Integer.parseInt(postcode);
425	            if (value < range[0] || value > range[1]) {
426	                throw new InvalidPostcodeException(postcode);
427	            }
428	        }
429	        return postcode;
430	    }
431	
432	    /**
433	     * Common street-type abbreviations expanded to their full word during address normalization.
434	     */
435	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
436	        "ST", "STREET",
437	        "RD", "ROAD",
438	        "AVE", "AVENUE");
439	
440	    /**
441	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
442	     * whitespace collapse to a single space, the value is upper-cased and common street-type
443	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
444	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
445	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
446	     * for every address comparison (household duplicate detection and the shared household id).
447	     *
448	     * @param address the raw address as submitted
449	     * @return the normalized address
450	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
451	     */
452	    private String normalizeAddress(String address) {
453	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
454	        if (collapsed.isEmpty()) {
455	            throw new InvalidAddressException(address);
456	        }
457	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
458	        StringBuilder normalized = new StringBuilder(collapsed.length());
459	        for (int i = 0; i < tokens.length; i++) {
460	            if (i > 0) {
461	                normalized.append(' ');
462	            }
463	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
464	        }
465	        return normalized.toString();
466	    }
467	
468	    /**
469	     * Rejects creating an owner whose identity duplicates an existing owner's. All duplicate detection
470	     * is consolidated here onto the identity-bearing part of the derived {@code identityKey}: two
471	     * owners are duplicates when they share the same normalized telephone and the same normalized email
472	     * (a {@code null} email compared as an empty segment). Existing telephones are re-normalized to
473	     * E.164 and existing emails lower-cased before comparison, so equivalent values submitted in
474	     * different formats (e.g. national {@code "0412 345 678"} and international {@code "+61 412 345 678"})
475	     * still match.
476	     * <p>
477	     * The {@code householdId} is deliberately not part of this comparison: a household is a shared
478	     * grouping, so two members of the same household with different telephones have different
479	     * identities and are both allowed. Only owners with the same telephone and email collide.
480	     *
481	     * @param owner the owner being created, with its telephone and email already normalized
482	     * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity
483	     */
484	    private void rejectDuplicateIdentity(Owner owner) {
485	        String identity = personalIdentity(owner.getTelephone(), owner.getEmail());
486	        boolean duplicate = this.clinicService.findAllOwners().stream()
487	            .anyMatch(existing -> identity.equals(
488	                personalIdentity(toE164OrNull(existing.getTelephone()), existing.getEmail())));
489	        if (duplicate) {
490	            String householdId = Households.householdId(owner.getLastName(), owner.getAddress());
491	            throw new DuplicateIdentityException(
492	                Households.identityKey(owner.getTelephone(), owner.getEmail(), householdId));
493	        }
494	    }
495	
496	    /**
497	     * Builds the identity-bearing prefix of the {@code identityKey} used for duplicate detection:
498	     * the normalized telephone and email joined with {@code '|'}, lower-casing the email (the form it
499	     * is stored in, see {@link #normalizeEmail}) so addresses differing only in letter case still match.
500	     */
501	    private String personalIdentity(String telephone, String email) {
502	        String normalizedEmail = email == null ? "" : email.toLowerCase(java.util.Locale.ROOT);
503	        return (telephone == null ? "" : telephone) + "|" + normalizedEmail;
504	    }
505	
506	    /**
507	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
508	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
509	     * when its national-number length does not match its country code.
510	     */
511	    private String toE164OrNull(String telephone) {
512	        try {
513	            return normalizeTelephone(telephone);
514	        } catch (InvalidTelephoneException e) {
515	            return null;
516	        }
517	    }
518	
519	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
520	    @Override
521	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
522	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
523	        if (currentOwner == null) {
524	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
525	        }
526	        currentOwner.setAddress(ownerFieldsDto.getAddress());
527	        currentOwner.setCity(ownerFieldsDto.getCity());
528	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
529	        currentOwner.setLastName(ownerFieldsDto.getLastName());
530	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
531	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
532	        this.clinicService.saveOwner(currentOwner);
533	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
534	    }
535	
536	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
537	    @Transactional
538	    @Override
539	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
540	        Owner owner = this.clinicService.findOwnerById(ownerId);
541	        if (owner == null) {
542	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
543	        }
544	        this.clinicService.deleteOwner(owner);
545	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
546	    }
547	
548	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
549	    @Override
550	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
551	        Owner owner = this.clinicService.findOwnerById(ownerId);
552	        if (owner == null) {
553	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
554	        }
555	        HttpHeaders headers = new HttpHeaders();
556	        Pet pet = petMapper.toPet(petFieldsDto);
557	        owner.setId(ownerId);
558	        pet.setOwner(owner);
559	        pet.getType().setName(null);
560	        this.clinicService.savePet(pet);
561	        PetDto petDto = petMapper.toPetDto(pet);
562	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
563	            .buildAndExpand(pet.getId()).toUri());
564	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
565	    }
566	
567	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
568	    @Override
569	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
570	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
571	        if (currentOwner != null) {
572	            Pet currentPet = this.clinicService.findPetById(petId);
573	            if (currentPet != null) {
574	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
575	                currentPet.setName(petFieldsDto.getName());
576	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
577	                this.clinicService.savePet(currentPet);
578	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
579	            }
580	        }
581	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
582	    }
583	
584	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
585	    @Override
586	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
587	        HttpHeaders headers = new HttpHeaders();
588	        Visit visit = visitMapper.toVisit(visitFieldsDto);
589	        Pet pet = new Pet();
590	        pet.setId(petId);
591	        visit.setPet(pet);
592	        this.clinicService.saveVisit(visit);
593	        VisitDto visitDto = visitMapper.toVisitDto(visit);
594	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
595	            .buildAndExpand(visit.getId()).toUri());
596	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
597	    }
598	
599	
600	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
601	    @Override
602	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
603	        Owner owner = this.clinicService.findOwnerById(ownerId);
604	        if (owner != null) {
605	            Pet pet = owner.getPet(petId);
606	            if (pet != null) {
607	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
608	            }
609	        }
610	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
611	    }
612	}
